data.package-catalog.py:
"""Read-once, allowlisted data catalog. No network access or per-request file IO."""

from copy import deepcopy
from dataclasses import asdict
from datetime import date, datetime
import math
from pathlib import Path
import re
from zoneinfo import ZoneInfo

from .core import Window, compare_energy
from .snapshots import Snapshot, read_json, read_snapshot
from .ev import ROLES, summarize_ev

MAX_SNAPSHOTS = 64
MAX_CATALOG_BYTES = 64 * 1024 * 1024
MAX_HISTORY_PAGE = 500
IDENTIFIER = re.compile(r"[A-Za-z0-9_-]{1,128}\Z")
DAY = re.compile(r"\d{4}-\d{2}-\d{2}\Z")


class QueryError(ValueError):
    """A fixed error code, safe to expose without filesystem paths or input values."""


def identifier(value):
    if not isinstance(value, str) or not IDENTIFIER.fullmatch(value):
        raise ValueError("Invalid catalog identifier")
    return value


def calendar_date(value):
    if not isinstance(value, str) or not DAY.fullmatch(value):
        raise QueryError("invalid_date")
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise QueryError("invalid_date") from None


def _keys(obj, required, optional=()):
    if not isinstance(obj, dict) or not set(required) <= obj.keys() or obj.keys() - set(required) - set(optional):
        raise ValueError("Invalid catalog fields")


def validate_ev_policy(policy, identities, energy):
    _keys(policy, set(ROLES), {"charging_state_item", "connection_state_item"})
    for item in policy.values():
        identifier(item)
    if len(set(policy.values())) != len(policy):
        raise ValueError("EV sources must be distinct")
    if set(policy.values()) & {energy["counter_item"], energy.get("power_item")}:
        raise ValueError("EV sources must be separate from house sources")
    for role, (kind, units) in ROLES.items():
        identity = identities.get(policy[role])
        if identity is not None and (identity[0] != kind or identity[1] not in units):
            raise ValueError("EV source has wrong kind or unit")


class Catalog:
    def __init__(self, config_path: Path):
        config, _ = read_json(config_path, 256 * 1024)
        _keys(config, {"schema_version", "sites"})
        if type(config["schema_version"]) is not int or config["schema_version"] != 1:
            raise ValueError("Unsupported catalog schema")
        if not isinstance(config["sites"], dict) or not 1 <= len(config["sites"]) <= 8:
            raise ValueError("Expected 1 to 8 configured sites")
        self._sites = deepcopy(config["sites"])
        self._snapshots: dict[tuple[str, str, str], Snapshot] = {}
        total_bytes = 0
        for site, settings in self._sites.items():
            identifier(site)
            _keys(settings, {"timezone", "instance", "origin", "snapshots", "energy"}, {"ev"})
            identifier(settings["instance"])
            ZoneInfo(settings["timezone"])
            if settings["origin"] not in {"direct", "mirror"}:
                raise ValueError("Invalid catalog origin")
            policy = settings["energy"]
            _keys(policy, {"counter_item", "label"}, {"power_item"})
            identifier(policy["counter_item"])
            if "power_item" in policy:
                identifier(policy["power_item"])
                if policy["power_item"] == policy["counter_item"]:
                    raise ValueError("Counter and comparator must be distinct")
            if not isinstance(policy["label"], str) or not 1 <= len(policy["label"]) <= 160:
                raise ValueError("An explicit reported-energy label is required")
            paths = settings["snapshots"]
            if not isinstance(paths, list) or not paths:
                raise ValueError("Snapshots must be explicitly listed")
            identities = {}
            for path in paths:
                if len(self._snapshots) >= MAX_SNAPSHOTS:
                    raise ValueError("Too many snapshots")
                if not isinstance(path, str) or not path or len(path) > 1024:
                    raise ValueError("Invalid snapshot path")
                snapshot = read_snapshot(config_path.parent / path)
                total_bytes += snapshot.size_bytes
                if total_bytes > MAX_CATALOG_BYTES:
                    raise ValueError("Catalog exceeds total size limit")
                source = snapshot.source
                identifier(source.item)
                if any(isinstance(v, str) and len(v) > 256 for v in asdict(source).values()):
                    raise ValueError("Source metadata too large")
                raw_unit = snapshot.history.get("unit")
                if raw_unit is not None and (not isinstance(raw_unit, str) or len(raw_unit) > 32):
                    raise ValueError("Invalid history unit metadata")
                if (source.site, source.instance, source.origin, snapshot.window.timezone_name) != (
                        site, settings["instance"], settings["origin"], settings["timezone"]):
                    raise ValueError("Snapshot identity does not match the configured site")
                day = snapshot.window.to_dict()["start"][:10]
                if snapshot.window.to_dict() != Window.day(day, settings["timezone"]).to_dict():
                    raise ValueError("This adapter requires whole calendar-day snapshots")
                key = (site, source.item, day)
                if key in self._snapshots:
                    raise ValueError("Ambiguous duplicate snapshot")
                identity = (source.kind, source.unit, source.backend)
                if source.item in identities and identities[source.item] != identity:
                    raise ValueError("Item semantics change between snapshots")
                identities[source.item] = identity
                # Only these bounded scalar fields can ever be returned as history.
                for row in snapshot.history["data"]:
                    t, state = row.get("time"), row.get("state")
                    if isinstance(t, bool) or not isinstance(t, (int, float)) or not math.isfinite(t):
                        raise ValueError("Invalid history timestamp")
                    if state is not None and not isinstance(state, (str, int, float, bool)):
                        raise ValueError("Invalid history state type")
                    if len(str(state)) > 256:
                        raise ValueError("History state too large")
                self._snapshots[key] = snapshot
            for field, kind in (("counter_item", "counter"), ("power_item", "power")):
                if field in policy:
                    item = policy[field]
                    # A configured but absent item is valid: no fallback or invented zero.
                    if item in identities and identities[item][0] != kind:
                        raise ValueError("Energy policy has the wrong measurement kind")
            if "ev" in settings:
                validate_ev_policy(settings["ev"], identities, policy)

    def _site(self, site):
        if site not in self._sites:
            raise QueryError("unknown_site")
        return self._sites[site]

    def _snapshot(self, site, item, day):
        self._site(site)
        calendar_date(day)
        if not any(s == site and i == item for s, i, _ in self._snapshots):
            raise QueryError("unknown_item")
        snapshot = self._snapshots.get((site, item, day))
        if snapshot is None:
            raise QueryError("snapshot_unavailable")
        return snapshot

    @staticmethod
    def _analysis(snapshot):
        result = deepcopy(snapshot.analysis)
        result["snapshot_sha256"] = snapshot.sha256
        result["captured_at"] = snapshot.captured_at
        return result

    def capabilities(self, site=None):
        if site is not None:
            self._site(site)
        sites = []
        for name, settings in sorted(self._sites.items()):
            if site is not None and name != site:
                continue
            items = []
            for item in sorted({i for s, i, _ in self._snapshots if s == name}):
                snapshots = [(d, snap) for (s, i, d), snap in self._snapshots.items() if (s, i) == (name, item)]
                items.append({"item": item, "kind": snapshots[0][1].source.kind,
                              "unit": snapshots[0][1].source.unit,
                              "dates": sorted(d for d, _ in snapshots)})
            sites.append({"site": name, "timezone": settings["timezone"], "instance": settings["instance"],
                          "today": datetime.now(ZoneInfo(settings["timezone"])).date().isoformat(),
                          "origin": settings["origin"], "energy_policy": settings["energy"], "items": items,
                          "ev_policy": settings.get("ev"), "ev_summary_available": "ev" in settings})
        return {"sites": deepcopy(sites), "period": "single_calendar_day", "live_data": False,
                "read_only": True, "history_page_max": MAX_HISTORY_PAGE,
                "history_order": "snapshot_order_with_duplicates", "end_sample": "integration_anchor",
                "snapshot_limit": MAX_SNAPSHOTS, "automatic_fallback": False}

    def statistics(self, site, item, day):
        return self._analysis(self._snapshot(site, item, day))

    def ev(self, site, day):
        settings = self._site(site)
        calendar_date(day)
        if "ev" not in settings:
            raise QueryError("ev_not_configured")
        policy = settings["ev"]
        snapshots = {role:self._snapshots.get((site, policy[role], day)) for role in ROLES}
        analyses = {role:self._analysis(snap) if snap else None for role,snap in snapshots.items()}
        return summarize_ev(site, Window.day(day, settings["timezone"]), policy, snapshots, analyses,
                            self.energy(site, day))

    def history(self, site, item, day, offset=0, limit=200):
        if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= MAX_HISTORY_PAGE:
            raise QueryError("invalid_pagination")
        snapshot = self._snapshot(site, item, day)
        start, end = snapshot.window.start.timestamp() * 1000, snapshot.window.end.timestamp() * 1000
        rows = [row for row in snapshot.history["data"] if start <= row["time"] <= end]
        if offset > len(rows):
            raise QueryError("invalid_pagination")
        page = [{"time": r["time"], "state": r.get("state")} for r in rows[offset:offset + limit]]
        return {"source": asdict(snapshot.source), "window": snapshot.window.to_dict(),
                "snapshot_sha256": snapshot.sha256, "raw_unit": snapshot.history.get("unit"),
                "points": page, "offset": offset, "returned": len(page), "total_points": len(rows),
                "next_offset": offset + len(page) if offset + len(page) < len(rows) else None,
                "end_sample": "integration_anchor", "order": "snapshot_order_with_duplicates",
                "analysis": self._analysis(snapshot)}

    def energy(self, site, day):
        settings = self._site(site)
        calendar_date(day)
        policy = settings["energy"]
        counter = self._snapshots.get((site, policy["counter_item"], day))
        power = self._snapshots.get((site, policy.get("power_item"), day))
        c = self._analysis(counter) if counter else None
        p = self._analysis(power) if power else None
        comparison = compare_energy(c, p) if c is not None and p is not None else None
        if comparison:
            comparison.pop("sources")  # Full analyses are already included below.
        warnings = set(c["issues"] if c else ["primary_snapshot_unavailable"])
        if p:
            warnings.update(p["issues"])
        if "power_item" in policy and power is None:
            warnings.add("comparison_snapshot_unavailable")
        if comparison:
            warnings.add(comparison["status"])
        return {"site": site, "window": Window.day(day, settings["timezone"]).to_dict(),
                "metric": "reported_load_energy", "label": policy["label"],
                "status": c["status"] if c else "insufficient_data",
                "reported_load_energy_kwh": c["value"] if c else None,
                "primary_item": policy["counter_item"], "primary": c,
                "power_integral_kwh": p["value"] if p else None, "power_check": p,
                "comparison": comparison, "warnings": sorted(warnings),
                "automatic_fallback": False, "house_energy_kwh": None,
                "physical_scope_verified": False}

data.package-collector.py:
"""One-shot, GET-only collection from explicitly configured local openHAB origins."""

import argparse
import base64
from dataclasses import asdict
from datetime import datetime, timezone
import hashlib
import http.client
import ipaddress
import json
import math
import os
from pathlib import Path
import socket
import ssl
import stat
import sys
import threading
import time
from urllib.parse import urlencode, urlsplit

from .catalog import Catalog, _keys, calendar_date, identifier, validate_ev_policy
from .core import MAX_POINTS, Source, Window, analyze
from .snapshots import MAX_FILE_BYTES, parse_json, read_json

MAX_RESPONSE_BYTES = 4 * 1024 * 1024
MAX_RUN_BYTES = 48 * 1024 * 1024
MAX_RUN_SECONDS = 300
QUERY_FLAGS = {"boundary": False, "itemState": False, "displayState": False}


class CollectionError(ValueError):
    """Only fixed codes are exposed; never include response bodies or credentials."""


def utc_now():
    return datetime.now(timezone.utc)


def validate_origin(base_url):
    if not isinstance(base_url, str) or len(base_url) > 256:
        raise CollectionError("invalid_origin")
    url = urlsplit(base_url)
    if (url.scheme not in {"http", "https"} or url.username is not None or url.password is not None
            or url.path not in {"", "/"} or url.query or url.fragment):
        raise CollectionError("invalid_origin")
    try:
        address = ipaddress.ip_address(url.hostname)
        port = url.port
    except (ValueError, TypeError):
        raise CollectionError("origin_requires_literal_private_ip") from None
    if (not (address.is_private or address.is_loopback or address in ipaddress.ip_network("100.64.0.0/10"))
            or address.is_unspecified or address.is_multicast or address.is_link_local):
        raise CollectionError("origin_requires_literal_private_ip")
    if port is not None and not 1 <= port <= 65535:
        raise CollectionError("invalid_origin_port")
    return url


def load_config(path):
    config, _ = read_json(path, 256 * 1024)
    _keys(config, {"schema_version", "sites"})
    if type(config["schema_version"]) is not int or config["schema_version"] != 1:
        raise CollectionError("unsupported_config_version")
    if not isinstance(config["sites"], dict) or not 1 <= len(config["sites"]) <= 8:
        raise CollectionError("invalid_sites")
    count = 0
    for site, settings in config["sites"].items():
        identifier(site)
        _keys(settings, {"base_url", "token_file", "instance", "timezone", "runtime_version", "energy", "items"},
              {"request_timeout_seconds", "ev"})
        validate_origin(settings["base_url"])
        identifier(settings["instance"])
        Window.day("2026-01-01", settings["timezone"])
        if not isinstance(settings["token_file"], str) or not 1 <= len(settings["token_file"]) <= 1024:
            raise CollectionError("invalid_token_path")
        if (not isinstance(settings["runtime_version"], str) or len(settings["runtime_version"]) > 32
                or not settings["runtime_version"].startswith(("5.1.", "5.2."))):
            raise CollectionError("unsupported_runtime_version")
        timeout = settings.get("request_timeout_seconds", 10)
        if type(timeout) not in (int, float) or not math.isfinite(timeout) or not 0 < timeout <= 30:
            raise CollectionError("invalid_timeout")
        policy = settings["energy"]
        _keys(policy, {"counter_item", "label"}, {"power_item"})
        if not isinstance(policy["label"], str) or not 1 <= len(policy["label"]) <= 160:
            raise CollectionError("invalid_energy_label")
        if not isinstance(settings["items"], dict) or not settings["items"]:
            raise CollectionError("invalid_items")
        for item, spec in settings["items"].items():
            identifier(item)
            _keys(spec, {"kind", "unit"}, {"expected_interval_seconds"})
            if type(spec.get("expected_interval_seconds", 60)) not in (int, float):
                raise CollectionError("invalid_sample_interval")
            Source(site=site, instance=settings["instance"], item=item, **spec)
            count += 1
        for field, kind in (("counter_item", "counter"), ("power_item", "power")):
            if field in policy:
                identifier(policy[field])
                if settings["items"].get(policy[field], {}).get("kind") != kind:
                    raise CollectionError("energy_policy_requires_configured_source")
        if "ev" in settings:
            identities = {i:(spec["kind"], spec["unit"]) for i,spec in settings["items"].items()}
            validate_ev_policy(settings["ev"], identities, policy)
            if any(settings["ev"][role] not in identities for role in ("power_item", "soc_item", "capacity_item")):
                raise CollectionError("ev_policy_requires_configured_sources")
    if count > 64:
        raise CollectionError("too_many_items")
    return config


def read_token(path):
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) & 0o077:
                raise CollectionError("token_file_permissions")
            raw = stream.read(16 * 1024 + 1)
        token = raw.decode("ascii").strip()
        if len(raw) > 16 * 1024 or not token or any(not 33 <= ord(c) <= 126 or c == ":" for c in token):
            raise CollectionError("invalid_token_file")
        return token
    except (OSError, UnicodeError):
        raise CollectionError("token_file_unavailable") from None


class OpenHABReader:
    """Fixed GET endpoints; no redirects, proxies, retries or reusable connections."""

    def __init__(self, settings, token_path, deadline, byte_budget=MAX_RUN_BYTES):
        self._url = validate_origin(settings["base_url"])
        self._authorization = "Basic " + base64.b64encode((read_token(token_path) + ":").encode()).decode()
        self._items = frozenset(settings["items"])
        self._timeout = settings.get("request_timeout_seconds", 10)
        self._deadline = deadline
        self._byte_budget = byte_budget
        self.bytes_received = 0
        self.requests = 0

    def runtime(self):
        return self._get("/rest/")[0]

    def persistence(self):
        return self._get("/rest/persistence")[0]

    def item(self, item):
        if item not in self._items:
            raise CollectionError("item_not_allowlisted")
        return self._get(f"/rest/items/{item}", {"metadata": "unit"})[0]

    def history(self, item, window):
        if item not in self._items:
            raise CollectionError("item_not_allowlisted")
        query = {"serviceId": "rrd4j", "starttime": window.start.isoformat(), "endtime": window.end.isoformat(),
                 "page": "0", "pagelength": str(MAX_POINTS),
                 **{key: "false" for key in QUERY_FLAGS}}
        payload, digest = self._get(f"/rest/persistence/items/{item}", query)
        return payload, digest, query

    def _get(self, path, query=None):
        allowed = {"/rest/", "/rest/persistence"} | {f"/rest/{prefix}/{i}" for i in self._items
                                                              for prefix in ("items", "persistence/items")}
        if path not in allowed:
            raise CollectionError("endpoint_not_allowlisted")
        budget = min(self._timeout, self._deadline - time.monotonic())
        if budget <= 0:
            raise CollectionError("collection_deadline_exceeded")
        connection_type = http.client.HTTPSConnection if self._url.scheme == "https" else http.client.HTTPConnection
        kwargs = {"context": ssl.create_default_context()} if self._url.scheme == "https" else {}
        connection = connection_type(self._url.hostname, self._url.port, timeout=budget, **kwargs)
        timer = None
        expired = threading.Event()
        started = time.monotonic()
        try:
            connection.connect()  # Literal IP: no unbounded DNS resolution.
            sock = connection.sock

            def interrupt():
                expired.set()
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass

            remaining = budget - (time.monotonic() - started)
            if remaining <= 0:
                raise CollectionError("request_timeout")
            timer = threading.Timer(remaining, interrupt)
            timer.daemon = True
            timer.start()
            target = path + ("?" + urlencode(query) if query else "")
            self.requests += 1
            connection.request("GET", target, headers={"Authorization": self._authorization,
                "Accept": "application/json", "Accept-Encoding": "identity", "Connection": "close"})
            response = connection.getresponse()
            if response.status != 200:
                raise CollectionError(f"http_{response.status}")
            if response.getheader("Content-Encoding", "identity").lower() != "identity":
                raise CollectionError("encoded_response_rejected")
            if response.getheader("Content-Type", "").split(";")[0].strip().lower() != "application/json":
                raise CollectionError("unexpected_content_type")
            length = response.getheader("Content-Length")
            if length is not None:
                if not length.isdecimal() or int(length) > MAX_RESPONSE_BYTES:
                    raise CollectionError("response_size_limit")
                if response.getheader("Transfer-Encoding"):
                    raise CollectionError("ambiguous_response_framing")
            chunks, size = [], 0
            while True:
                chunk = response.read1(min(65536, MAX_RESPONSE_BYTES + 1 - size))
                if not chunk:
                    break
                size += len(chunk)
                self.bytes_received += len(chunk)
                if size > MAX_RESPONSE_BYTES or self.bytes_received > self._byte_budget:
                    raise CollectionError("response_size_limit")
                chunks.append(chunk)
            if expired.is_set():
                raise CollectionError("request_timeout")
            if length is not None and size != int(length):
                raise CollectionError("truncated_response")
            raw = b"".join(chunks)
            try:
                doc = parse_json(raw)
            except (ValueError, UnicodeError, RecursionError):
                raise CollectionError("invalid_json_response") from None
            return doc, hashlib.sha256(raw).hexdigest()
        except (OSError, http.client.HTTPException):
            raise CollectionError("request_timeout" if expired.is_set() or time.monotonic() - started >= budget
                                  else "connection_failed") from None
        finally:
            if timer is not None:
                timer.cancel()
                timer.join()
            connection.close()


def unit_evidence(metadata, source):
    if not isinstance(metadata, dict) or metadata.get("name") != source.item:
        raise CollectionError("item_identity_mismatch")
    allowed_types = {"counter": {"Number:Energy"}, "energy": {"Number:Energy"}, "power": {"Number:Power"},
                     "temperature": {"Number:Temperature"}, "number": {"Number", "Number:Dimensionless"},
                     "switch": {"Switch", "Contact"}}
    if metadata.get("type") not in allowed_types[source.kind]:
        raise CollectionError("item_type_mismatch")
    if source.kind == "switch":
        return {"item_type": metadata["type"], "unit": "state", "method": "binary_item_type"}
    try:
        configured = (metadata.get("metadata") or {}).get("unit", {}).get("value")
        symbol = metadata.get("unitSymbol")
    except (AttributeError, TypeError):
        raise CollectionError("invalid_unit_metadata") from None
    observed = [value for value in (configured, symbol) if value is not None]
    if not observed or any(value != source.unit for value in observed):
        raise CollectionError("item_unit_mismatch")
    return {"item_type": metadata["type"], "unit": source.unit, "unit_metadata": configured,
            "unit_symbol": symbol, "method": "live_item_metadata"}


def validate_history(history, source, window):
    if not isinstance(history, dict) or history.get("name") != source.item:
        raise CollectionError("history_identity_mismatch")
    rows = history.get("data")
    if not isinstance(rows, list) or len(rows) >= MAX_POINTS:
        raise CollectionError("history_point_limit_or_possible_truncation")
    count = history.get("datapoints")
    if type(count) is int:
        expected = count
    elif isinstance(count, str) and count.isdecimal() and len(count) < 8:
        expected = int(count)
    else:
        raise CollectionError("invalid_history_count")
    if expected != len(rows):
        raise CollectionError("history_count_mismatch")
    if history.get("unit") not in (None, source.unit):
        raise CollectionError("history_unit_mismatch")
    begin, end = window.start.timestamp() * 1000, window.end.timestamp() * 1000
    for row in rows:
        if not isinstance(row, dict):
            raise CollectionError("invalid_history_row")
        stamp, value = row.get("time"), row.get("state")
        if type(stamp) not in (int, float) or not math.isfinite(stamp) or not begin <= stamp <= end:
            raise CollectionError("history_timestamp_outside_query")
        if value is not None and type(value) not in (str, int, float, bool):
            raise CollectionError("invalid_history_state")
        if len(str(value)) > 256:
            raise CollectionError("history_state_size_limit")
    # Keep original point order and binary duplicates. Do not repair invalid states/resets.
    clean = {"name": history["name"], "datapoints": expected,
             "data": [{"time": row["time"], "state": row.get("state")} for row in rows]}
    if "unit" in history:
        clean["unit"] = history["unit"]
    analyze(clean, source, window)
    return clean


def write_private(path, doc):
    raw = (json.dumps(doc, ensure_ascii=False, allow_nan=False, separators=(",", ":")) + "\n").encode()
    if len(raw) > MAX_FILE_BYTES:
        raise CollectionError("snapshot_size_limit")
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def collect(config_path, day, output, *, site=None, now=None):
    config = load_config(config_path)
    calendar_date(day)
    if site is not None and site not in config["sites"]:
        raise CollectionError("unknown_site")
    sites = {s: cfg for s, cfg in config["sites"].items() if site is None or s == site}
    observed_now = now or utc_now()
    if observed_now.tzinfo is None:
        raise CollectionError("clock_requires_timezone")
    windows = {s: Window.day(day, cfg["timezone"]) for s, cfg in sites.items()}
    if any(w.end.timestamp() > observed_now.timestamp() for w in windows.values()):
        raise CollectionError("only_completed_calendar_days")
    # Exclusive directory: existing collections are never modified or reused after failure.
    output.mkdir(mode=0o700, parents=False, exist_ok=False)
    catalog = {"schema_version": 1, "sites": {}}
    report = {"schema_version": 1, "started_at": utc_now().isoformat(), "date": day,
              "status": "collecting", "method": "GET", "requests": 0, "bytes_received": 0, "snapshots": []}
    deadline = time.monotonic() + MAX_RUN_SECONDS
    current_site, current_item = None, None
    try:
        for current_site, settings in sites.items():
            current_item = None
            token_path = Path(settings["token_file"]).expanduser()
            if not token_path.is_absolute():
                token_path = config_path.parent / token_path
            reader = OpenHABReader(settings, token_path, deadline, MAX_RUN_BYTES - report["bytes_received"])
            runtime = reader.runtime()
            if not isinstance(runtime, dict) or runtime.get("runtimeInfo", {}).get("version") != settings["runtime_version"]:
                raise CollectionError("runtime_version_changed")
            services = reader.persistence()
            if not isinstance(services, list) or not any(isinstance(s, dict) and s.get("id") == "rrd4j"
                                                       and s.get("type") == "Queryable" for s in services):
                raise CollectionError("rrd4j_not_queryable")
            entry = {"instance": settings["instance"], "origin": "direct", "timezone": settings["timezone"],
                     "energy": settings["energy"], "snapshots": []}
            catalog["sites"][current_site] = entry
            if "ev" in settings:
                entry["ev"] = settings["ev"]
            for current_item, spec in settings["items"].items():
                source = Source(site=current_site, instance=settings["instance"], item=current_item,
                                origin="direct", backend="rrd4j", unit_evidence="item_metadata", **spec)
                metadata = reader.item(current_item)
                evidence = unit_evidence(metadata, source)
                evidence["observed_at"] = utc_now().isoformat()
                evidence["runtime_version"] = settings["runtime_version"]
                payload, digest, params = reader.history(current_item, windows[current_site])
                history = validate_history(payload, source, windows[current_site])
                snapshot = {"schema_version": 1, "captured_at": utc_now().isoformat(), "evidence": evidence,
                            "source": asdict(source), "window": windows[current_site].to_dict(),
                            "query": QUERY_FLAGS, "request": {"method": "GET", "parameters": params},
                            "response_sha256": digest, "history": history}
                filename = f"{current_site}-{current_item}-{day}.json"
                write_private(output / filename, snapshot)
                entry["snapshots"].append(filename)
                result = analyze(history, source, windows[current_site])
                report["snapshots"].append({"site": current_site, "item": current_item, "file": filename,
                    "response_sha256": digest, "status": result["status"], "issues": result["issues"],
                    "points": len(history["data"]), "value": result["value"], "unit": result["unit"]})
                if report["bytes_received"] + reader.bytes_received > MAX_RUN_BYTES:
                    raise CollectionError("collection_size_limit")
            report["requests"] += reader.requests
            report["bytes_received"] += reader.bytes_received
        write_private(output / ".catalog.pending.json", catalog)
        Catalog(output / ".catalog.pending.json")  # Same validation the MCP server will use.
        report["status"] = "complete"
        report["finished_at"] = utc_now().isoformat()
        write_private(output / "collection.json", report)
        os.replace(output / ".catalog.pending.json", output / "catalog.json")
        return report
    except Exception as error:
        failure = {"status": "failed", "site": current_site, "item": current_item,
                   "error": str(error) if isinstance(error, CollectionError) else "invalid_data_or_local_io",
                   "finished_at": utc_now().isoformat()}
        try:
            write_private(output / "failure.json", failure)
        except OSError:
            pass
        raise CollectionError(failure["error"]) from None


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--date", required=True, help="Completed calendar day YYYY-MM-DD in each site's timezone")
    parser.add_argument("--output", required=True, type=Path, help="New local directory; its parent must exist")
    parser.add_argument("--site", help="Collect only this configured site; default: all sites")
    args = parser.parse_args()
    try:
        report = collect(args.config, args.date, args.output, site=args.site)
        print(json.dumps({k: report[k] for k in ("status", "date", "requests", "bytes_received")}
                         | {"snapshots": len(report["snapshots"])}, ensure_ascii=False))
    except (OSError, ValueError, TypeError, KeyError, AttributeError, RecursionError) as error:
        code = str(error) if isinstance(error, CollectionError) else "invalid_config_or_local_io"
        print(f"Collection failed: {code}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

data.package-core.py:
"""Conservative calculations over bounded openHAB REST history snapshots.

Intervals are [start, end); a sample at end is accepted as an integration anchor.
No extrapolation, gap filling, reset repair or inference of sensor freshness.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import date, datetime, time, timedelta, timezone
import math
import re
from typing import Any
from zoneinfo import ZoneInfo

MAX_POINTS = 100_000
MAX_WINDOW_SECONDS = 31 * 25 * 3600
UNITS = {
    "Wh": ("energy", 0.001, 0.0, "kWh"),
    "kWh": ("energy", 1.0, 0.0, "kWh"),
    "W": ("power", 0.001, 0.0, "kW"),
    "kW": ("power", 1.0, 0.0, "kW"),
    "°C": ("temperature", 1.0, 0.0, "°C"),
    "K": ("temperature", 1.0, -273.15, "°C"),
    "%": ("number", 1.0, 0.0, "%"),
    "1": ("number", 1.0, 0.0, "1"),
}
DIMENSIONS = {"counter": "energy", "energy": "energy", "power": "power", "temperature": "temperature", "number": "number"}
NUMBER = re.compile(r"^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(.*?)$")


@dataclass(frozen=True)
class Window:
    start: datetime
    end: datetime
    timezone_name: str = "Europe/Stockholm"

    def __post_init__(self) -> None:
        ZoneInfo(self.timezone_name)
        if any(t.tzinfo is None or t.utcoffset() is None for t in (self.start, self.end)):
            raise ValueError("Window requires timezone-aware timestamps")
        if not 0 < self.seconds <= MAX_WINDOW_SECONDS:
            raise ValueError("Window must be positive and at most 31 * 25 hours")

    @classmethod
    def day(cls, day: str, timezone_name: str = "Europe/Stockholm") -> Window:
        d = date.fromisoformat(day)
        tz = ZoneInfo(timezone_name)
        return cls(datetime.combine(d, time.min, tz), datetime.combine(d + timedelta(days=1), time.min, tz), timezone_name)

    @property
    def seconds(self) -> float:
        # Subtraction of two datetimes with the same ZoneInfo ignores DST changes.
        return self.end.timestamp() - self.start.timestamp()

    def to_dict(self) -> dict[str, Any]:
        tz = ZoneInfo(self.timezone_name)
        return {"start": self.start.astimezone(tz).isoformat(), "end": self.end.astimezone(tz).isoformat(),
                "start_utc": self.start.astimezone(timezone.utc).isoformat(),
                "end_utc": self.end.astimezone(timezone.utc).isoformat(),
                "timezone": self.timezone_name, "seconds": self.seconds, "interval": "[start,end)"}


@dataclass(frozen=True)
class Source:
    site: str
    instance: str
    item: str
    kind: str
    unit: str
    origin: str = "direct"
    backend: str = "rrd4j"
    expected_interval_seconds: float = 60
    consolidation: str = "unknown"
    historical_freshness: str = "unknown"
    unit_evidence: str = "declared"

    def __post_init__(self) -> None:
        if not all(isinstance(x, str) and x for x in (self.site, self.instance, self.item, self.backend)):
            raise ValueError("Source identity is required")
        if self.kind not in {*DIMENSIONS, "switch"}:
            raise ValueError("Unsupported measurement kind")
        if self.origin not in {"direct", "mirror"}:
            raise ValueError("Origin must be direct or mirror")
        if self.historical_freshness not in {"unknown", "verified", "stale"}:
            raise ValueError("Invalid historical freshness")
        if self.unit_evidence not in {"declared", "item_metadata"}:
            raise ValueError("Invalid unit evidence")
        if not math.isfinite(self.expected_interval_seconds) or self.expected_interval_seconds <= 0:
            raise ValueError("Expected interval must be positive and finite")
        if self.kind == "switch":
            if self.unit != "state":
                raise ValueError("Switch unit must be state")
        elif self.unit not in UNITS or UNITS[self.unit][0] != DIMENSIONS[self.kind]:
            raise ValueError("Source unit does not match measurement kind")


def _value(state: Any, unit: str, kind: str) -> float | str | None:
    if kind == "switch":
        return state if isinstance(state, str) and state in {"ON", "OFF", "OPEN", "CLOSED"} else None
    if isinstance(state, bool) or not isinstance(state, (str, int, float)):
        return None
    match = NUMBER.fullmatch(str(state).strip())
    if not match:
        return None
    number, suffix = match.groups()
    actual_unit = suffix or unit
    # Reject mixed units within one response rather than silently guessing semantics.
    if actual_unit != unit:
        return None
    value = float(number)
    result = value * UNITS[unit][1] + UNITS[unit][2]
    return result if math.isfinite(result) else None


def analyze(payload: dict[str, Any], source: Source, window: Window, *,
            boundary: bool = False, item_state: bool = False) -> dict[str, Any]:
    """Calculate one metric. Callers must preserve the original query flags.

    value is a whole-window result only. covered_value is explicitly partial when
    coverage is incomplete. Unknown freshness remains visible even at 100% coverage.
    """
    if boundary is not False or item_state is not False:
        raise ValueError("Synthetic boundary/current-state points are not accepted")
    if not isinstance(payload, dict) or payload.get("name") != source.item:
        raise ValueError("History item does not match source")
    issues: set[str] = set()
    unit = payload.get("unit")
    if source.kind != "switch":
        if unit is None and source.unit_evidence == "item_metadata":
            # openHAB 5.1 history omits unit; only explicitly verified item metadata
            # permits interpreting its bare numeric states. Never guess from a label.
            unit = source.unit
            issues.add("unit_from_item_metadata")
        if unit not in UNITS or UNITS[unit][0] != DIMENSIONS[source.kind]:
            raise ValueError("History unit is missing or has wrong dimension")
        if UNITS[unit][3] != UNITS[source.unit][3]:
            raise ValueError("History unit does not match source semantics")
    rows = payload.get("data")
    if not isinstance(rows, list) or len(rows) > MAX_POINTS:
        raise ValueError("History must be a list within the point limit")
    if source.historical_freshness == "unknown":
        issues.add("historical_freshness_unknown")
    if source.consolidation != "raw":
        issues.add("persisted_samples_may_be_consolidated")
    if source.origin == "mirror":
        issues.add("mirrored_source")
    start, end = window.start.timestamp() * 1000, window.end.timestamp() * 1000
    by_time: dict[float, float | str | None] = {}
    invalid_timestamp = False
    duplicate_count = 0
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("Malformed history row")
        t = row.get("time")
        if isinstance(t, bool) or not isinstance(t, (int, float)) or not math.isfinite(t):
            invalid_timestamp = True
            issues.add("invalid_timestamp")
            continue
        if not start <= t <= end:
            issues.add("outside_window_points_ignored")
            continue
        v = _value(row.get("state"), unit, source.kind)
        if v is None:
            issues.add("invalid_state")
        if t in by_time:
            duplicate_count += 1
            if source.kind == "switch":
                # openHAB REST emits previous state then actual state at transitions.
                issues.add("binary_chart_duplicates_normalized")
            elif by_time[t] != v:
                # Preserve an invalid gap anchor: never integrate across ambiguity.
                v = None
                issues.add("conflicting_duplicate")
        by_time[t] = v
    points = sorted(by_time.items())
    valid = [(t, v) for t, v in points if v is not None]
    max_gap = source.expected_interval_seconds * 1.5
    intervals = []
    resets = 0
    for (ta, a), (tb, b) in zip(points, points[1:]):
        seconds = (tb - ta) / 1000
        if source.kind == "counter" and a is not None and b is not None:
            tolerance = max(1e-9, abs(a) * 1e-12)
            if b < a - tolerance:
                resets += 1
        if seconds > max_gap:
            issues.add("gap_exceeds_expected_interval")
            continue
        if a is None or b is None:
            continue
        intervals.append((seconds, a, b))
    covered_seconds = sum(d for d, _, _ in intervals)
    coverage = covered_seconds / window.seconds
    complete = math.isclose(covered_seconds, window.seconds, rel_tol=0, abs_tol=1e-6)
    if not complete:
        issues.add("incomplete_coverage")
    if resets:
        issues.add("counter_decrease_or_reset")
    if source.kind == "counter" and any(v < 0 for _, v in valid):
        issues.add("negative_counter")
    stale = source.historical_freshness == "stale"
    if stale:
        issues.add("historical_source_stale")
    fatal = invalid_timestamp or bool(issues & {"counter_decrease_or_reset", "negative_counter", "conflicting_duplicate"})
    value = None
    covered_value = None
    stats: dict[str, Any] = {}
    if source.kind == "counter":
        method, output_unit = "counter_boundary_difference", "kWh"
        if complete and not fatal and points:
            # Endpoint difference avoids accumulating tiny floating-point oscillations.
            value = max(0.0, points[-1][1] - points[0][1])
        stats["detected_decreases"] = resets
    elif source.kind == "switch":
        states = {v for _, v in valid}
        if states & {"ON", "OFF"} and states & {"OPEN", "CLOSED"}:
            fatal = True
            issues.add("mixed_binary_domains")
        method, output_unit = "sampled_left_hold_active_duration", "h"
        covered_value = sum(d for d, a, _ in intervals if a in {"ON", "OPEN"}) / 3600 if intervals else None
        value = covered_value if complete else None
        stats["active_states"] = ["ON", "OPEN"]
        stats["sampled_transitions"] = sum(a != b for _, a, b in intervals)
        issues.add("runtime_estimated_from_samples")
    else:
        integral = sum(d * (a / 2 + b / 2) for d, a, b in intervals)
        stats["sample_min"] = min((v for _, v in valid), default=None)
        stats["sample_max"] = max((v for _, v in valid), default=None)
        stats["time_weighted_mean_over_covered_intervals"] = integral / covered_seconds if covered_seconds else None
        if source.kind == "power":
            method, output_unit = "trapezoidal_power_integral", "kWh"
            covered_value = integral / 3600 if intervals else None
            value = covered_value if complete else None
        else:
            method, output_unit = "trapezoidal_time_weighted_mean", UNITS[source.unit][3]
            covered_value = stats["time_weighted_mean_over_covered_intervals"]
            value = covered_value if complete else None
    numeric_outputs = [value, covered_value, *stats.values()]
    if any(isinstance(v, (int, float)) and not math.isfinite(v) for v in numeric_outputs):
        issues.add("numeric_overflow")
        fatal = True
        covered_value = None
        stats = {k: None if isinstance(v, (int, float)) and not math.isfinite(v) else v for k, v in stats.items()}
    if fatal or stale:
        value = None
    status = "stale" if stale else "invalid_data" if fatal else "insufficient_data" if value is None else "estimated"
    steps = [(b[0] - a[0]) / 1000 for a, b in zip(points, points[1:])]
    return {"schema_version": 1, "source": asdict(source), "window": window.to_dict(), "status": status,
            "method": method, "value": value, "unit": output_unit, "covered_value": covered_value,
            "coverage": {"seconds": covered_seconds, "fraction": coverage, "sensor_availability": "not_inferred"},
            "samples": {"received": len(rows), "unique_in_window": len(points), "valid": len(valid),
                        "duplicates": duplicate_count, "min_step_seconds": min(steps, default=None),
                        "max_step_seconds": max(steps, default=None)},
            "statistics": stats, "issues": sorted(issues)}


def compare_energy(counter: dict[str, Any], power: dict[str, Any], *,
                   relative_tolerance: float = 0.05, absolute_tolerance_kwh: float = 0.1,
                   scope_verified: bool = False) -> dict[str, Any]:
    """Cross-check candidates; matching numbers alone do not verify meter scope."""
    if any(not math.isfinite(x) or x < 0 for x in (relative_tolerance, absolute_tolerance_kwh)):
        raise ValueError("Tolerances must be finite and nonnegative")
    if not isinstance(scope_verified, bool):
        raise ValueError("scope_verified must be boolean")
    if counter["source"]["kind"] != "counter" or power["source"]["kind"] != "power":
        raise ValueError("Expected counter and power results")
    if counter["source"]["site"] != power["source"]["site"] or counter["window"] != power["window"]:
        raise ValueError("Energy comparison requires the same site and time window")
    a, b = counter["value"], power["value"]
    out = {"schema_version": 1, "site": counter["source"]["site"], "window": counter["window"],
           "status": "insufficient_data", "house_energy_kwh": None, "counter_kwh": a, "power_integral_kwh": b,
           "difference_kwh": None, "difference_fraction_of_power": None,
           "scope_verified": scope_verified, "tolerance": {"relative": relative_tolerance, "absolute_kwh": absolute_tolerance_kwh},
           "sources": [counter, power]}
    if a is None or b is None:
        return out
    if a < 0 or b < 0:
        out["status"] = "invalid_house_energy"
        return out
    difference = a - b
    out["difference_kwh"] = difference
    ratio = difference / b if b else None
    out["difference_fraction_of_power"] = ratio if ratio is not None and math.isfinite(ratio) else None
    # Relative error uses power integral as reference, as in the investigation.
    threshold = max(absolute_tolerance_kwh, relative_tolerance * abs(b))
    if abs(difference) > threshold:
        out["status"] = "conflicting_sources"
    elif not scope_verified:
        out["status"] = "consistent_candidates_scope_unverified"
    elif any(r["source"]["historical_freshness"] != "verified" for r in (counter, power)):
        out["status"] = "consistent_candidates_freshness_unverified"
    else:
        out["status"] = "estimated"
        out["house_energy_kwh"] = a
    return out

data.package-daily.py:
"""Local daily collection and atomic publication. No openHAB writes.

The scheduler owns collection; MCP only reads immutable local generations.
An index keeps 31 queryable days, loading at most one day's catalog per request.
Archived files are never deleted automatically.
"""

import argparse
from contextlib import contextmanager
from copy import deepcopy
from datetime import datetime, timedelta, time, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sys
import uuid
from zoneinfo import ZoneInfo

from .catalog import Catalog, QueryError, calendar_date
from .collector import CollectionError, collect, load_config, write_private
from .snapshots import read_json

MAX_DAYS = 31
MAX_DAYS_PER_RUN = 3
TZ = "Europe/Stockholm"
RUN_PATH = re.compile(r"runs/[0-9a-f]{32}/catalog\.json\Z")


def now_utc():
    return datetime.now(timezone.utc)


def atomic_json(path, document):
    """Same-filesystem replace after fsync; never truncate the visible file."""
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.pending")
    try:
        write_private(temporary, document)
        os.replace(temporary, path)
        fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    finally:
        temporary.unlink(missing_ok=True)


@contextmanager
def exclusive(root):
    root.mkdir(mode=0o700, parents=False, exist_ok=True)
    if root.is_symlink() or root.stat().st_uid != os.getuid() or root.stat().st_mode & 0o077:
        raise ValueError("private_daily_root_required")
    fd = os.open(root / ".lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            yield False
            return
        yield True
    finally:
        os.close(fd)


def target_day(now, hour, minute):
    if now.tzinfo is None:
        raise ValueError("timezone_required")
    local = now.astimezone(ZoneInfo(TZ))
    return local.date() - timedelta(days=1 if local.time() >= time(hour, minute) else 2)


def read_index(root):
    index, _ = read_json(root / "active.json", 1024 * 1024)
    if type(index.get("schema_version")) is not int or index["schema_version"] != 1 or index.get("kind") != "daily_catalog_index":
        raise ValueError("invalid_daily_index")
    if not re.fullmatch(r"[0-9a-f]{32}", index["generation"]):
        raise ValueError("invalid_generation")
    if datetime.fromisoformat(index["published_at"]).tzinfo is None:
        raise ValueError("invalid_publication_time")
    calendar_date(index["start_date"])
    if (index.get("timezone") != TZ or type(index["hour"]) is not int or not 0 <= index["hour"] < 24
            or type(index["minute"]) is not int or not 0 <= index["minute"] < 60):
        raise ValueError("invalid_daily_schedule")
    days = index["days"]
    if not isinstance(days, dict) or not 1 <= len(days) <= MAX_DAYS:
        raise ValueError("invalid_daily_days")
    for day, record in days.items():
        calendar_date(day)
        if not RUN_PATH.fullmatch(record["catalog"]) or not re.fullmatch(r"[0-9a-f]{64}", record["sha256"]):
            raise ValueError("invalid_daily_reference")
        if not isinstance(record["snapshots"], dict) or not 1 <= len(record["snapshots"]) <= 64:
            raise ValueError("invalid_snapshot_digests")
        for name, digest in record["snapshots"].items():
            if Path(name).name != name or not re.fullmatch(r"[0-9a-f]{64}", digest):
                raise ValueError("invalid_snapshot_digest")
    if not isinstance(index["sites"], list) or not 1 <= len(index["sites"]) <= 8:
        raise ValueError("invalid_daily_sites")
    return index


def layout(catalog, day):
    """Public metadata, excluding dates/today; all configured series must exist."""
    sites = catalog.capabilities()["sites"]
    for site in sites:
        site.pop("today")
        for item in site["items"]:
            if item.pop("dates") != [day]:
                raise ValueError("expected_one_complete_day")
    return sites


def checked_catalog(root, reference, day):
    path = root / reference["catalog"]
    if not path.resolve().is_relative_to(root.resolve()) or path.is_symlink():
        raise ValueError("catalog_path_outside_root")
    document, raw = read_json(path, 256 * 1024)
    if hashlib.sha256(raw).hexdigest() != reference["sha256"]:
        raise ValueError("catalog_digest_mismatch")
    seen = set()
    for entry in document["sites"].values():
        for name in entry["snapshots"]:
            source = path.parent / name
            if Path(name).name != name or source.is_symlink() or not source.resolve().is_relative_to(path.parent.resolve()):
                raise ValueError("snapshot_path_outside_generation")
            _, snapshot_raw = read_json(source)
            if hashlib.sha256(snapshot_raw).hexdigest() != reference["snapshots"].get(name):
                raise ValueError("snapshot_digest_mismatch")
            seen.add(name)
    if seen != set(reference["snapshots"]):
        raise ValueError("snapshot_digest_set_mismatch")
    catalog = Catalog(path)
    layout(catalog, day)
    return catalog


def commit(root, index, output, day):
    """Validate before publication; never change a previous generation."""
    path = output / "catalog.json"
    document, raw = read_json(path, 256 * 1024)
    digests = {}
    for entry in document["sites"].values():
        for name in entry["snapshots"]:
            if Path(name).name != name:
                raise ValueError("snapshot_path_outside_generation")
            _, snapshot_raw = read_json(output / name)
            digests[name] = hashlib.sha256(snapshot_raw).hexdigest()
    reference = {"catalog": str(path.relative_to(root)), "sha256": hashlib.sha256(raw).hexdigest(),
                 "snapshots": digests}
    catalog = checked_catalog(root, reference, day)
    if layout(catalog, day) != index["sites"]:
        raise ValueError("source_policy_or_item_layout_changed")
    updated = deepcopy(index)
    updated["days"][day] = reference
    updated["days"] = dict(sorted(updated["days"].items())[-MAX_DAYS:])
    updated["generation"] = uuid.uuid4().hex
    updated["published_at"] = now_utc().isoformat()
    for directory in (output, output.parent):
        fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    atomic_json(root / "active.json", updated)
    return updated


def initialize(root, seed, hour=4, minute=15):
    """Import a known single-day seed without network or credential access."""
    if not 0 <= hour < 24 or not 0 <= minute < 60:
        raise ValueError("invalid_daily_schedule")
    with exclusive(root) as acquired:
        if not acquired or (root / "active.json").exists():
            raise ValueError("daily_root_already_initialized_or_busy")
        catalog = Catalog(seed)
        dates = {d for s in catalog.capabilities()["sites"] for i in s["items"] for d in i["dates"]}
        if len(dates) != 1:
            raise ValueError("single_day_seed_required")
        day = dates.pop()
        sites = layout(catalog, day)
        if any(s["timezone"] != TZ for s in sites):
            raise ValueError("daily_scheduler_requires_stockholm")
        (root / "runs").mkdir(mode=0o700, exist_ok=True)
        output = root / "runs" / uuid.uuid4().hex
        output.mkdir(mode=0o700)
        document, _ = read_json(seed, 256 * 1024)
        for entry in document["sites"].values():
            copied = []
            for name in entry["snapshots"]:
                dest = uuid.uuid4().hex + ".json"
                shutil.copyfile(seed.parent / name, output / dest)
                (output / dest).chmod(0o600)
                with (output / dest).open("rb") as stream:
                    os.fsync(stream.fileno())
                copied.append(dest)
            entry["snapshots"] = copied
        write_private(output / "catalog.json", document)
        index = {"schema_version": 1, "kind": "daily_catalog_index", "timezone": TZ,
                 "hour": hour, "minute": minute, "start_date": day, "sites": sites, "days": {}}
        commit(root, index, output, day)
        atomic_json(root / "status.json", {"status": "seeded", "finished_at": now_utc().isoformat()})


def desired_days(index, now):
    target = target_day(now, index["hour"], index["minute"])
    start = max(calendar_date(index["start_date"]), target - timedelta(days=MAX_DAYS - 1))
    return [(target - timedelta(days=i)).isoformat() for i in range(max(0, (target - start).days + 1))]


def run(root, config_path, *, now=None, refresh_date=None):
    observed = now or now_utc()
    with exclusive(root) as acquired:
        if not acquired:
            return {"status": "busy"}
        attempted = None
        try:
            index = read_index(root)
            config = load_config(config_path)
            # Configuration changes require explicit local re-initialization, not silent source replacement.
            settings = {s["site"]: s for s in index["sites"]}
            if set(config["sites"]) != set(settings):
                raise ValueError("sites_changed")
            for name, cfg in config["sites"].items():
                old = settings[name]
                identities = {(i["item"], i["kind"], i["unit"]) for i in old["items"]}
                if (cfg["energy"] != old["energy_policy"] or cfg.get("ev") != old["ev_policy"]
                        or cfg["instance"] != old["instance"] or cfg["timezone"] != TZ
                        or identities != {(i, v["kind"], v["unit"]) for i, v in cfg["items"].items()}):
                    raise ValueError("source_policy_or_item_layout_changed")
            pending = [d for d in desired_days(index, observed) if d not in index["days"]]
            if refresh_date is not None:
                calendar_date(refresh_date)
                if refresh_date not in desired_days(index, observed):
                    raise ValueError("refresh_date_not_due")
                pending = [refresh_date]
            if not pending:
                return {"status": "up_to_date", "latest_date": max(index["days"])}
            completed = []
            for attempted in pending[:MAX_DAYS_PER_RUN]:
                atomic_json(root / "status.json", {"status": "collecting", "date": attempted,
                            "started_at": observed.isoformat()})
                output = root / "runs" / uuid.uuid4().hex
                report = collect(config_path, attempted, output, now=observed)
                index = commit(root, index, output, attempted)
                completed.append(attempted)
                atomic_json(root / "status.json", {"status": "success", "date": attempted,
                            "finished_at": now_utc().isoformat(), "requests": report["requests"],
                            "quality_issues": sum(bool(s["issues"]) for s in report["snapshots"])})
            return {"status": "success", "published_dates": completed,
                    "pending_days": len(pending) - len(completed)}
        except Exception as error:
            code = str(error) if isinstance(error, CollectionError) else "invalid_config_data_or_local_io"
            failure = {"status": "failed", "date": attempted, "error": code,
                       "finished_at": now_utc().isoformat()}
            atomic_json(root / "status.json", failure)
            return failure


class DailyCatalog:
    """No network. Each request sees one coherent committed manifest."""

    def __init__(self, root):
        self.root = root
        self.request_view()  # Fail startup if no valid manifest is present.

    def request_view(self):
        try:
            return DailyView(self.root, read_index(self.root))
        except (OSError, ValueError, TypeError, KeyError, AttributeError):
            raise QueryError("daily_catalog_unavailable") from None


class DailyView:
    def __init__(self, root, index):
        self.root, self.index = root, index

    def collection_status(self):
        index = self.index
        now = now_utc()
        pending = [d for d in desired_days(index, now) if d not in index["days"]]
        try:
            status, _ = read_json(self.root / "status.json", 4096)
            state = status["status"]
            if state not in {"seeded", "success", "collecting", "failed"}:
                state = "unknown"
            if state == "collecting":
                started = datetime.fromisoformat(status["started_at"])
                if started.tzinfo is None or (now - started).total_seconds() > 1200:
                    state = "interrupted"
        except (OSError, ValueError, KeyError, TypeError, AttributeError):
            state = "unknown"
        return {"automatic_daily_collection": True, "timezone": TZ,
                "scheduled_local_time": f"{index['hour']:02}:{index['minute']:02}",
                "generation": index["generation"], "published_at": index["published_at"],
                "latest_available_date": max(index["days"]),
                "expected_through_date": target_day(now, index["hour"], index["minute"]).isoformat(),
                "pending_days": len(pending), "last_attempt_status": state,
                "local_snapshot_only": True, "queryable_day_limit": MAX_DAYS}

    def capabilities(self, site=None):
        sites = self._catalog(max(self.index["days"])).capabilities(site)["sites"]
        for s in sites:
            s["today"] = now_utc().astimezone(ZoneInfo(s["timezone"])).date().isoformat()
            for item in s["items"]:
                item["dates"] = sorted(self.index["days"])
        return {"sites": [s for s in sites if site is None or site == s["site"]],
                "period": "single_calendar_day", "live_data": False, "read_only": True,
                "history_page_max": 500, "automatic_fallback": False,
                "history_order": "snapshot_order_with_duplicates", "end_sample": "integration_anchor"}

    def _catalog(self, day):
        calendar_date(day)
        # Missing dates still go to the exact-date Catalog APIs, which return missing/null, never a different day.
        selected = day if day in self.index["days"] else max(self.index["days"])
        try:
            catalog = checked_catalog(self.root, self.index["days"][selected], selected)
            if layout(catalog, selected) != self.index["sites"]:
                raise ValueError("catalog_layout_changed")
            return catalog
        except (OSError, ValueError, TypeError, KeyError, AttributeError):
            raise QueryError("daily_catalog_unavailable") from None

    def energy(self, site, day):
        return self._catalog(day).energy(site, day)

    def ev(self, site, day):
        return self._catalog(day).ev(site, day)

    def statistics(self, site, item, day):
        return self._catalog(day).statistics(site, item, day)

    def history(self, site, item, day, offset=0, limit=200):
        return self._catalog(day).history(site, item, day, offset, limit)


def collection_warning(info):
    messages = []
    if info["last_attempt_status"] == "failed":
        messages.append("Den senaste automatiska insamlingen misslyckades. Tidigare publicerade dygn har behållits.")
    if info["last_attempt_status"] == "interrupted":
        messages.append("Den senaste automatiska insamlingen verkar ha avbrutits. Tidigare publicerade dygn har behållits.")
    if info["pending_days"]:
        messages.append("Den automatiska insamlingen saknar ett eller flera förväntade dygn. Saknade datum ersätts inte med äldre data.")
    if info["last_attempt_status"] == "unknown":
        messages.append("Status för den automatiska insamlingen kunde inte läsas.")
    return " ".join(messages)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", required=True, type=Path)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--seed", type=Path)
    parser.add_argument("--hour", type=int, default=4)
    parser.add_argument("--minute", type=int, default=15)
    parser.add_argument("--refresh-date")
    args = parser.parse_args()
    try:
        if args.seed:
            initialize(args.root, args.seed, args.hour, args.minute)
            result = {"status": "initialized"}
        elif args.config:
            result = run(args.root, args.config, refresh_date=args.refresh_date)
        else:
            parser.error("--config or --seed is required")
        print(json.dumps(result, ensure_ascii=False))
        return 2 if result["status"] == "failed" else 0
    except (OSError, ValueError, TypeError, KeyError, AttributeError):
        print("Daily collection failed: invalid configuration or local IO", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

data.package-snapshots.py:
"""Bounded snapshot loading shared by the CLI and the offline MCP adapter."""

from dataclasses import dataclass
from datetime import datetime
import hashlib
import json
import math
from pathlib import Path

from .core import Source, Window, analyze

MAX_FILE_BYTES = 8 * 1024 * 1024


def _nonfinite(value):
    raise ValueError("Non-finite JSON number")


def _finite_float(value):
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("Non-finite JSON number")
    return number


def _unique_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def parse_json(raw: bytes):
    """Strict JSON for both saved envelopes and bounded HTTP response bodies."""
    return json.loads(raw, parse_constant=_nonfinite, parse_float=_finite_float, object_pairs_hook=_unique_keys)


def read_json(path: Path, limit: int = MAX_FILE_BYTES) -> tuple[dict, bytes]:
    if not path.is_file():
        raise ValueError("Expected a regular JSON file")
    with path.open("rb") as stream:
        raw = stream.read(limit + 1)
    if len(raw) > limit:
        raise ValueError(f"JSON file exceeds {limit / (1024 * 1024):g} MiB size limit")
    doc = parse_json(raw)
    if not isinstance(doc, dict):
        raise ValueError("JSON document must be an object")
    return doc, raw


@dataclass(frozen=True)
class Snapshot:
    source: Source
    window: Window
    history: dict
    analysis: dict
    sha256: str
    size_bytes: int
    captured_at: str | None


def read_snapshot(path: Path) -> Snapshot:
    doc, raw = read_json(path)
    if type(doc.get("schema_version")) is not int or doc["schema_version"] != 1:
        raise ValueError("Unsupported snapshot schema")
    query = doc["query"]
    if any(query.get(key) is not False for key in ("boundary", "itemState", "displayState")):
        raise ValueError("Snapshot must record boundary=false, itemState=false, displayState=false")
    source = Source(**doc["source"])
    w = doc["window"]
    window = Window(datetime.fromisoformat(w["start"]), datetime.fromisoformat(w["end"]), w["timezone"])
    analysis = analyze(doc["history"], source, window)
    captured_at = doc.get("captured_at")
    if captured_at is not None:
        if not isinstance(captured_at, str) or len(captured_at) > 64:
            raise ValueError("Invalid capture timestamp")
        captured = datetime.fromisoformat(captured_at)
        if captured.tzinfo is None or captured.utcoffset() is None:
            raise ValueError("Capture timestamp requires timezone")
        captured_at = captured.isoformat()
    return Snapshot(source, window, doc["history"], analysis, hashlib.sha256(raw).hexdigest(), len(raw), captured_at)

data.package-voice.py:
"""Deterministic Swedish speech text; no model calls or reinterpretation of sources."""

from datetime import date

MONTHS = ("januari", "februari", "mars", "april", "maj", "juni", "juli", "augusti", "september", "oktober", "november", "december")
SITES = {"huddinge": "Huddinge", "landet": "Landet"}
ITEM_LABELS = {
    "Compressor_State_Value_as_Switch": "kompressorns aktiva tid",
    "Warm_Water_Temperature_Value_as_Number": "varmvattentemperaturens medelvärde",
    "Outdoor_Temperature_Value_as_Number": "utetemperaturens medelvärde",
}
UNITS = {"kWh": "kilowattimmar", "kW": "kilowatt", "W": "watt", "°C": "grader Celsius",
         "%": "procent", "1": "", "h": "timmar"}


def spoken_date(value):
    day = date.fromisoformat(value[:10])
    return f"den {day.day} {MONTHS[day.month - 1]} {day.year}"


def amount(value, unit):
    if unit == "h":
        minutes = round(value * 60)
        hours, rest = divmod(minutes, 60)
        return f"{hours} timmar och {rest} minuter"
    return (f"{value:.2f}".replace(".", ",") + " " + UNITS.get(unit, unit)).strip()


def speech_summary(name, data):
    if name == "get_history_capabilities":
        parts = []
        for site in data["sites"]:
            days = sorted({day for item in site["items"] for day in item["dates"]})
            place = SITES.get(site["site"], site["site"])
            parts.append(f"{place} har {len(days)} sparade dygn. Senaste datum är {spoken_date(days[-1])}.")
        return " ".join(parts) + " Det är sparad historik; jag hämtar inte nya värden i samtalet."
    if name == "get_ev_charging_summary":
        place = SITES.get(data["site"], data["site"])
        text = f"Bilens historik i {place}, {spoken_date(data['window']['start'])}. "
        value = data["reported_power_integral_kwh"]
        if data["charging_observation"] == "positive_power_observed":
            text += f"Historiken visar {data['observed_period_count']} perioder med positiv rapporterad laddeffekt. "
        elif data["charging_observation"] == "no_positive_power_in_saved_samples":
            text += "Ingen positiv laddeffekt finns i de sparade punkterna. Det bevisar inte att bilen inte laddade. "
        if value is None:
            text += "Ett värde från laddeffekten för hela dygnet saknas. Saknade data räknas inte som noll. "
        else:
            text += f"Effektkurvan motsvarar uppskattningsvis {amount(value, 'kWh')}. "
        duration = data['sampled_positive_power_minutes']
        if duration is not None:
            text += f"Uppskattad tid med positiv rapporterad effekt är {amount(duration/60, 'h')}; det är inte inkopplingstid. "
        battery = data["battery"]
        before, after = battery["soc_before_first_period_percent"], battery["soc_after_last_period_percent"]
        if before is not None and after is not None:
            text += f"Laddnivån var {amount(before, '%')} före första perioden och {amount(after, '%')} efter den sista. "
        increase = battery["calculated_increase_during_observed_periods_kwh"]
        if increase is not None:
            text += f"Beräknat batteritillskott under perioderna är {amount(increase, 'kWh')}, från kapacitet gånger procentändring. "
            text += "Det är ingen oberoende energimätning. "
        else:
            text += "Ett komplett beräknat batteritillskott under laddperioderna saknas. "
        if not data["periods_complete_for_day"]:
            text += "Laddperiodernas gränser eller dygnstäckning är ofullständiga. "
        if data["periods_truncated"]:
            text += "Detaljlistan visar bara de första perioderna. "
        text += ("API-effektens mätpunkt är okänd. Bilens AC-förbrukning från huset har inte beräknats, "
                 "och ingen bilenergi dras av från husets primära energiräknare. "
                 "Historik för laddstatus och anslutningsstatus saknas i denna sammanfattning. "
                 "Bilens laddplats kan inte avgöras av dessa uppgifter.")
        issues = data["warnings"]
        if "historical_source_stale" in issues:
            text += " En historisk källa är markerad som inaktuell."
    elif name == "get_energy_summary":
        place = SITES.get(data["site"], data["site"])
        value = data["reported_load_energy_kwh"]
        metric = "Sigenergy-rapporterad lastenergi" if data["site"] == "landet" else data["label"]
        text = f"{place}, {spoken_date(data['window']['start'])}. "
        if value is None:
            text += f"Jag kan inte ange {metric.lower()} för hela dygnet från energiräknaren. "
            text += "Saknade eller ogiltiga data räknas inte som noll, och effektkurvan används inte som ersättning."
        else:
            text += f"{metric} är uppskattningsvis {amount(value, 'kWh')}, enligt energiräknaren."
        comparison = data["comparison"]
        if comparison and comparison["status"] == "conflicting_sources":
            text += f" Effektkurvan motsvarar {amount(data['power_integral_kwh'], 'kWh')} och avviker tydligt."
        elif comparison and comparison["status"] == "invalid_house_energy":
            text += " Effektkontrollen kan inte tolkas som husets förbrukning."
        elif "comparison_snapshot_unavailable" in data["warnings"] or (data["power_check"] and data["power_check"]["value"] is None):
            text += " En komplett effektkontroll saknas."
        if "counter_decrease_or_reset" in data["warnings"]:
            text += " Räknaren har minskat eller återställts."
        if "historical_source_stale" in data["warnings"]:
            text += " En historisk källa är markerad som inaktuell."
        text += " Den fysiska mätomfattningen är inte verifierad."
        issues = data["warnings"]
    else:
        result = data["analysis"] if name == "get_item_history" else data
        source = result["source"]
        place = SITES.get(source["site"], source["site"])
        kind = source["kind"]
        metric = ITEM_LABELS.get(source["item"], {"counter": "energiräknarens ökning", "energy": "energivärdets tidsviktade medelvärde", "power": "energin beräknad från effektkurvan",
            "switch": "den valda signalens aktiva tid", "temperature": "den valda temperaturens medelvärde",
            "number": "den valda seriens medelvärde"}[kind])
        text = f"{place}, {spoken_date(result['window']['start'])}. "
        if result["value"] is None:
            text += "Ett tillförlitligt värde för hela dygnet saknas. Saknade data räknas inte som noll."
        else:
            text += f"Uppskattningsvis är {metric} {amount(result['value'], result['unit'])}."
        if kind == "switch":
            text += " Detta är aktiv tid, inte energiförbrukning."
        if result["coverage"]["fraction"] < 1:
            text += " Historiken har inte full beräkningsbar täckning."
        if name == "get_item_history" and data["next_offset"] is not None:
            text += " Fler historikpunkter finns på nästa sida; analysen gäller hela dygnet."
        issues = result["issues"]
        if "historical_source_stale" in issues:
            text += " Den historiska källan är markerad som inaktuell."
    if "historical_freshness_unknown" in issues:
        text += " Sensorns historiska färskhet är inte verifierad."
    if "persisted_samples_may_be_consolidated" in issues:
        text += " Historiken kan vara aggregerad."
    if "mirrored_source" in issues:
        text += " Källan är speglad."
    return text

data.gateway.py:
"""Fixed-destination, GET-only Landet gateway through loopback SOCKS5.

No tokens on disk, no URL/credential logging, no redirects or arbitrary targets.
"""
import argparse
from datetime import datetime
import http.client
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import ipaddress
import json
from pathlib import Path
import re
import socket
import struct
import threading
from urllib.parse import parse_qsl, urlencode, urlsplit
from openhab_analytics.collector import MAX_RESPONSE_BYTES, QUERY_FLAGS
from openhab_analytics.core import MAX_POINTS


def request_target(target, items):
    if len(target) > 2048 or not target.startswith('/') or target.startswith('//'):
        raise ValueError('invalid_target')
    u = urlsplit(target)
    if u.scheme or u.netloc or u.fragment or '%' in u.path or '\\' in u.path:
        raise ValueError('invalid_target')
    pairs = parse_qsl(u.query, keep_blank_values=True, strict_parsing=True, max_num_fields=10)
    q = dict(pairs)
    if len(q) != len(pairs):
        raise ValueError('duplicate_query')
    if u.path in {'/rest/', '/rest/persistence'}:
        if q: raise ValueError('query_not_allowed')
    elif any(u.path == '/rest/items/' + i for i in items):
        if q != {'metadata': 'unit'}: raise ValueError('metadata_only')
    elif any(u.path == '/rest/persistence/items/' + i for i in items):
        if set(q) != {'serviceId', 'starttime', 'endtime', 'page', 'pagelength', *QUERY_FLAGS}:
            raise ValueError('invalid_history_query')
        if q['serviceId'] != 'rrd4j' or q['page'] != '0' or q['pagelength'] != str(MAX_POINTS):
            raise ValueError('invalid_history_bounds')
        if any(q[k] != 'false' for k in QUERY_FLAGS): raise ValueError('unsafe_history_flags')
        start, end = (datetime.fromisoformat(q[k]) for k in ('starttime', 'endtime'))
        if start.tzinfo is None or end.tzinfo is None or not 0 < (end-start).total_seconds() <= 25*3600:
            raise ValueError('invalid_history_window')
    else:
        raise ValueError('endpoint_not_allowlisted')
    return u.path + ('?' + urlencode(pairs) if pairs else '')


def recv_exact(sock, size):
    chunks = bytearray()
    while len(chunks) < size:
        part = sock.recv(size-len(chunks))
        if not part: raise OSError('socks_closed')
        chunks.extend(part)
    return bytes(chunks)


def socks_connect(proxy, upstream, timeout=8):
    address = ipaddress.IPv4Address(upstream[0])
    sock = socket.create_connection(proxy, timeout=timeout)
    try:
        sock.sendall(b'\x05\x01\x00')
        if recv_exact(sock, 2) != b'\x05\x00': raise OSError('socks_auth')
        sock.sendall(b'\x05\x01\x00\x01' + address.packed + struct.pack('!H', upstream[1]))
        ver, status, reserved, atyp = recv_exact(sock, 4)
        if (ver, status, reserved) != (5, 0, 0): raise OSError('socks_connect')
        if atyp == 1: size = 4
        elif atyp == 4: size = 16
        elif atyp == 3: size = recv_exact(sock, 1)[0]
        else: raise OSError('socks_address')
        recv_exact(sock, size+2)
        return sock
    except Exception:
        sock.close()
        raise


class Gateway(ThreadingHTTPServer):
    daemon_threads = True
    def __init__(self, address, config):
        ip = ipaddress.IPv4Address(config['upstream_host'])
        if not ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_unspecified:
            raise ValueError('private_fixed_upstream_required')
        if not 1 <= config['upstream_port'] <= 65535: raise ValueError('invalid_port')
        items = config['items']
        if not items or any(not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', i) for i in items):
            raise ValueError('invalid_items')
        self.items = frozenset(items)
        self.upstream = (str(ip), config['upstream_port'])
        self.proxy = ('127.0.0.1', config.get('socks_port', 1055))
        self.slots = threading.BoundedSemaphore(8)
        super().__init__(address, Handler)

    def process_request(self, request, address):
        if not self.slots.acquire(blocking=False):
            request.close()
            return
        try: super().process_request(request, address)
        except Exception:
            self.slots.release()
            raise

    def process_request_thread(self, request, address):
        try: super().process_request_thread(request, address)
        finally: self.slots.release()

    def handle_error(self, request, client_address):
        pass  # Never print request, headers, URLs or exception text.


class Handler(BaseHTTPRequestHandler):
    server_version = 'AnalyticsGateway'
    sys_version = ''
    def setup(self):
        self.request.settimeout(10)
        super().setup()

    def log_message(self, *args): pass

    def reply(self, status, body=b'{}', content_type='application/json'):
        self.send_response(status)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Connection', 'close')
        self.end_headers()
        self.wfile.write(body)
        self.close_connection = True

    def do_GET(self):
        if self.path == '/healthz':
            self.reply(200)
            return
        if self.path == '/readyz':
            try:
                with socks_connect(self.server.proxy, self.server.upstream): pass
                self.reply(200)
            except Exception: self.reply(503)
            return
        try:
            target = request_target(self.path, self.server.items)
            auth = self.headers.get_all('Authorization', [])
            if len(auth) != 1 or not re.fullmatch(r'Basic [A-Za-z0-9+/=]{4,12000}', auth[0]):
                self.reply(401); return
            if self.headers.get_all('Transfer-Encoding') or self.headers.get_all('Content-Length', []) not in ([], ['0']):
                self.reply(400); return
        except (ValueError, KeyError, TypeError):
            self.reply(403); return
        connection = http.client.HTTPConnection(*self.server.upstream, timeout=8)
        timer = None
        try:
            connection.sock = socks_connect(self.server.proxy, self.server.upstream)
            sock = connection.sock
            def stop():
                try: sock.shutdown(socket.SHUT_RDWR)
                except OSError: pass
            timer = threading.Timer(9, stop); timer.daemon = True; timer.start()
            connection.request('GET', target, headers={'Authorization': auth[0], 'Accept': 'application/json',
                'Accept-Encoding': 'identity', 'Connection': 'close'})
            response = connection.getresponse()
            if response.status != 200:
                self.reply(response.status if response.status in (401,403,404,429) else 502); return
            if response.getheader('Content-Encoding','identity') != 'identity' or response.getheader('Content-Type','').split(';')[0] != 'application/json':
                raise ValueError('unexpected_response')
            lengths = response.headers.get_all('Content-Length', [])
            if lengths and (len(lengths) != 1 or not lengths[0].isdecimal() or int(lengths[0]) > MAX_RESPONSE_BYTES or response.getheader('Transfer-Encoding')):
                raise ValueError('invalid_response_framing')
            body = response.read(MAX_RESPONSE_BYTES+1)
            if len(body)>MAX_RESPONSE_BYTES: raise ValueError('response_limit')
            self.reply(200,body)
        except Exception:
            self.reply(502)
        finally:
            if timer: timer.cancel()
            connection.close()

    def denied(self): self.reply(405)
    do_POST = do_PUT = do_DELETE = do_PATCH = do_CONNECT = do_HEAD = do_OPTIONS = do_TRACE = denied


if __name__ == '__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--config',type=Path,default=Path('/config/gateway.json'))
    args=parser.parse_args()
    Gateway(('0.0.0.0',8081),json.loads(args.config.read_text())).serve_forever()
